DROP TABLE G_US_STATES PURGE;

CREATE TABLE G_US_STATES 
(
  GID        NUMBER(10,0) NOT NULL ENABLE, 
  STATE      VARCHAR2(2), 
  STATE_FIPS VARCHAR2(2), 
  GEOG4326   MDSYS.SDO_GEOMETRY , 
  CONSTRAINT G_US_STATES_PK PRIMARY KEY (GID)
);

REM INSERTING into G_US_STATES

SET DEFINE OFF;

BEGIN
END;
/

VALUES ('G_US_STATES', 
        'GEOG4326', 
        MDSYS.SDO_DIM_ARRAY(MDSYS.SDO_DIM_ELEMENT('Longitude', -124.755790710449, -66.954002380371, 0.005), MDSYS.SDO_DIM_ELEMENT('Latitude', 24.518321990967, 49.385620117188, 0.005)),
        4326);

CREATE INDEX G_US_STATES_GEOG4326_SPIX ON G_US_STATES (GEOG4326) 
   INDEXTYPE IS MDSYS.SPATIAL_INDEX  PARAMETERS ('sdo_indx_dims=2, layer_gtype=MULTIPOLYGON, geodetic=true');
